function access(){msg('خريطة أدوار محلية للتجربة. لا تمنح حماية فعلية دون خدمة هوية وخادم. مدير الموقع يحتاج نطاق موقع محدد، والمقيّم يحتاج قائمة موظفين مكلف بهم.','Local role mapping only. Real protection requires identity and server services. Site managers require an explicit site scope; assessors require assigned employees.');searchable(F().bindings,[['email',t('البريد','Email')],['employee_code',t('الموظف','Employee')],['role',t('الدور','Role')],['org_code',t('نطاق الوحدة','Unit scope')],['site',t('نطاق الموقع','Site scope')]]);const f=form(A.content,v=>{v.email=v.email.trim().toLowerCase();if(F().bindings.some(b=>b.email===v.email&&b.employee_code!==v.employee_code||b.employee_code===v.employee_code&&b.email!==v.email))throw Error('الربط بريد ↔ موظف يجب أن يكون فريدًا 1:1');if(v.role==='site_manager'&&!v.site.trim())throw Error('نطاق الموقع مطلوب');const assigned=v.assigned.split(/[,،\s]+/).filter(Boolean),ids=new Set(people().map(e=>String(e.employee_code)));if(assigned.some(x=>!ids.has(x)))throw Error('كود موظف غير موجود في النطاق');commit('access.bind',v.employee_code,()=>upsert(F().bindings,'employee_code',{...v,assigned}))});field(f,'email','البريد الإلكتروني','Email','',null,true,'email');field(f,'employee_code','الموظف','Employee','',people().map(e=>[e.employee_code,e.employee_ar]),true);field(f,'role','الدور','Role','employee',Object.entries(M.roles).map(([k,v])=>[k,t(v[0],v[1])]),true);field(f,'org_code','نطاق الوحدة','Unit scope','',[['','—'],...A.orgs.filter(o=>!company()||o.company_code===company()).map(o=>[o.org_code,o.org_ar])]);field(f,'site','نطاق الموقع الدقيق','Exact site scope');field(f,'assigned','أكواد الموظفين المكلف بهم المقيّم','Assigned employee IDs');}
function notifications(){const rows=[],today=new Date().toISOString().slice(0,10);for(const e of people()){for(const [key,label,lead]of [['contract_end',t('نهاية العقد','Contract end'),60],['probation_end',t('نهاية التجربة','Probation end'),+F().settings.probationLead]]){const d=M.daysUntil(e[key],today);if(d===null||d>lead)continue;const bucket=d<0?'overdue':key==='contract_end'?d<=15?15:d<=30?30:60:lead;rows.push({id:e.employee_code+':'+key+':'+e[key]+':'+bucket,employee:e.employee_ar,type:label,date:e[key],days:d})}}const ids=new Set(people().map(e=>String(e.employee_code)));for(const q of F().workflowRequests.filter(q=>q.status==='pending'&&ids.has(q.employee_code))){const step=q.steps[q.step],due=new Date(Date.parse(q.step_started)+step.sla*86400000).toISOString().slice(0,10);if(M.daysUntil(due,today)<0)rows.push({id:q.id+':'+q.step,employee:q.employee_code,type:t('اعتماد متأخر','Overdue approval'),date:due,days:M.daysUntil(due,today)})}return rows}
function notificationPage(){msg('تُحسب التنبيهات عند فتح المنصة أو التحديث: العقد 60/30/15 يومًا، التجربة حسب الإعداد، وتأخر خطوات الاعتماد. إرسال البريد والجدولة الخلفية غير متصلين.','Alerts are calculated on page load or refresh: contracts at 60/30/15 days, configured probation lead time and overdue approvals. Email and background scheduling are not connected.');const rows=notifications().map(r=>({...r,read:F().read.includes(r.id)?t('مقروء','Read'):t('جديد','New')}));searchable(rows,[['employee',t('الموظف','Employee')],['type',t('التنبيه','Alert')],['date',t('الاستحقاق','Due date')],['days',t('الأيام المتبقية','Days remaining')],['read',t('الحالة','Status')]]);A.button(t('تحديد الكل كمقروء','Mark all read'),()=>{commit('notifications.read','notifications',()=>F().read=[...new Set([...F().read,...rows.map(r=>r.id)])]);A.draw()});if(editor()){const f=form(A.content,v=>commit('settings.alerts','settings',()=>F().settings.probationLead=+v.lead));const d=field(f,'lead','تنبيه التجربة قبل (أيام)','Probation lead (days)',F().settings.probationLead,null,true,'number');d.min=1;d.max=180;}}
function templates(){msg('القوالب التجريبية مسودات لبيئة المقاولات؛ لا تنشئ تقييمات أو نتائج موظفين. كل حفظ يُنشئ إصدارًا محفوظًا مستقلًا.','Construction sample templates are drafts; they do not create employee evaluations or scores. Each save creates an independent version.');const area=N('div');A.content.append(area);const list=N('div',undefined,'foundation-grid');area.append(list);F().templates.slice().reverse().forEach(v=>{const c=N('article',undefined,'foundation-card');c.append(N('h3',v.name_ar),N('span','v'+v.version+' · '+(v.sample?t('تجريبي','Sample'):t('مسودة','Draft')),'foundation-tag'),N('p',v.name_en||''));A.button(t('عرض / إصدار جديد','Preview / new version'),()=>edit(v),c);list.append(c)});A.button(t('قالب جديد','New template'),()=>edit({id:id(),version:0,name_ar:'',name_en:'',sections:[{title_ar:'القسم الأول',title_en:'Section 1',questions:[{id:id(),text_ar:'',text_en:'',type:'text',scale:5,weight:0,required:true}]}]}));const editorArea=N('div');A.content.append(editorArea);function edit(old){editorArea.replaceChildren();const draft=clone(old),f=form(editorArea,v=>{draft.name_ar=v.name_ar;draft.name_en=v.name_en;M.validateTemplate(draft);commit('template.version',draft.id,()=>{const version=Math.max(0,...F().templates.filter(t=>t.id===draft.id).map(t=>t.version))+1;F().templates.push({...draft,version,status:'draft',created:new Date().toISOString()})})});field(f,'name_ar','اسم القالب العربي','Arabic template name',draft.name_ar,null,true);field(f,'name_en','اسم القالب الإنجليزي','English template name',draft.name_en);const sections=N('div',undefined,'wide');f.insertBefore(sections,f.lastChild);function build(){sections.replaceChildren();draft.sections.forEach((s,si)=>{const box=N('div',undefined,'foundation-question');const title=N('input');title.value=s.title_ar;title.required=true;title.setAttribute('aria-label','عنوان القسم العربي');title.oninput=()=>s.title_ar=title.value;const titleEn=N('input');titleEn.value=s.title_en||'';titleEn.placeholder='Section title in English';titleEn.oninput=()=>s.title_en=titleEn.value;box.append(title,titleEn);s.questions.forEach((q,qi)=>{const row=N('div',undefined,'foundation-question'),text=N('input'),en=N('input'),type=N('select'),scale=N('input'),weight=N('input'),required=N('input');text.value=q.text_ar;text.required=true;text.placeholder=t('نص السؤال العربي','Arabic question');text.setAttribute('aria-label',text.placeholder);text.oninput=()=>q.text_ar=text.value;en.value=q.text_en||'';en.placeholder='Question in English';en.oninput=()=>q.text_en=en.value;['text','textarea','number','rating','boolean'].forEach(v=>type.add(new Option(v,v)));type.value=q.type;type.setAttribute('aria-label','نوع السؤال / Question type');type.onchange=()=>q.type=type.value;scale.type=weight.type='number';scale.min=2;scale.max=10;scale.value=q.scale||5;scale.setAttribute('aria-label','حد المقياس / Scale maximum');scale.oninput=()=>q.scale=+scale.value;weight.min=0;weight.value=q.weight||0;weight.setAttribute('aria-label','الوزن / Weight');weight.oninput=()=>q.weight=+weight.value;required.type='checkbox';required.checked=q.required;required.onchange=()=>q.required=required.checked;const l=N('label',t('إلزامي','Required'));l.append(required);row.append(text,en,type,scale,weight,l);A.button(t('حذف السؤال','Remove question'),()=>{s.questions.splice(qi,1);build()},row);box.append(row)});A.button(t('إضافة سؤال','Add question'),()=>{s.questions.push({id:id(),text_ar:'',text_en:'',type:'text',scale:5,weight:0,required:true});build()},box);A.button(t('حذف القسم','Remove section'),()=>{draft.sections.splice(si,1);build()},box);sections.append(box)})}build();A.button(t('إضافة قسم','Add section'),()=>{draft.sections.push({title_ar:'قسم جديد',title_en:'',questions:[]});build()},editorArea);A.button(t('معاينة النموذج','Preview form'),()=>{const d=N('dialog'),wrap=N('div');wrap.append(N('h2',draft.name_ar||t('معاينة','Preview')));draft.sections.forEach(s=>{wrap.append(N('h3',s.title_ar));s.questions.forEach(q=>{const l=N('label',q.text_ar),input=N(q.type==='textarea'?'textarea':'input');if(q.type!=='textarea')input.type=q.type==='rating'||q.type==='number'?'number':q.type==='boolean'?'checkbox':'text';input.required=q.required;if(q.type==='rating'){input.min=1;input.max=q.scale}l.append(input);wrap.append(l,N('br'))})});A.button(t('إغلاق','Close'),()=>{d.close();d.remove()},wrap);d.append(wrap);document.body.append(d);d.showModal()},editorArea);editorArea.scrollIntoView({block:'nearest'})}
heading('استيراد أسئلة من مستند','Import questions from a document');const upload=N('input');upload.type='file';upload.accept='.docx,.xlsx,.pdf';upload.setAttribute('aria-label','Word Excel PDF');const result=N('div');A.content.append(upload,result);upload.onchange=async()=>{const file=upload.files[0];if(!file)return;result.replaceChildren(N('p',t('جارٍ الاستخراج للمراجعة…','Extracting for review…')));try{if(file.size>8*1024*1024)throw Error('الحد الأقصى 8MB');const res=await fetch('/api/foundation/template-extract',{method:'POST',headers:{'X-File-Type':file.name.split('.').pop().toLowerCase()},body:file}),v=await res.json();if(!res.ok)throw Error(v.error);result.replaceChildren(N('p',t('اختر النصوص التي تمثل أسئلة. لا يُعتمد المحتوى تلقائيًا.','Select text that represents questions. Content is never approved automatically.')));const chosen=new Set(),f=N('div');v.lines.forEach((text,i)=>{const l=N('label',text),c=N('input');c.type='checkbox';c.onchange=()=>c.checked?chosen.add(i):chosen.delete(i);l.prepend(c);f.append(l,N('br'))});result.append(f);A.button(t('إنشاء مسودة من المحدد','Draft selected questions'),()=>{if(!chosen.size)return;edit({id:id(),version:0,name_ar:file.name,name_en:'',source:file.name,sections:[{title_ar:'أسئلة مستخرجة — للمراجعة',title_en:'Extracted — review required',questions:[...chosen].sort((a,b)=>a-b).map(i=>({id:id(),text_ar:v.lines[i],text_en:'',type:'text',weight:0,required:true,scale:5}))}]})},result);if(!v.lines.length)msg('لا يوجد نص قابل للاستخراج؛ المستند الممسوح يحتاج OCR.','No extractable text; scanned documents require OCR.',result)}catch(e){result.replaceChildren(N('p',e.message,'foundation-error'))}};
}
function workflows(){msg('ابدأ بخطوات واضحة الأدوار والمُعتمدين. يُحفظ مسار الطلب كنسخة مستقلة. لا يستطيع مقدم الطلب اعتماد طلبه بنفسه.','Configure explicit roles and approvers. Each request stores an independent workflow snapshot. Requesters cannot approve their own requests.');searchable(F().workflowDefs,[['name',t('المسار','Workflow')],['version',t('الإصدار','Version')],['description',t('الخطوات','Steps')]]);const f=form(A.content,v=>{const steps=JSON.parse(v.steps);if(!Array.isArray(steps)||!steps.length||steps.length>10)throw Error('المسار يحتاج 1–10 خطوات');for(const s of steps){if(!M.roles[s.role]||s.role==='top_management'||!Number.isInteger(+s.sla)||s.sla<1||s.sla>365)throw Error('راجع دور الخطوة ومهلة SLA');if(s.assignee&&!A.employees.some(e=>String(e.employee_code)===String(s.assignee)))throw Error('المعتمد غير مسجل')}commit('workflow.definition',v.name,()=>{const previous=F().workflowDefs.filter(d=>d.name===v.name);F().workflowDefs.push({id:previous[0]?.id||id(),name:v.name,version:Math.max(0,...previous.map(d=>d.version))+1,steps,description:steps.map(s=>s.label||s.role).join(' ← ')})})});field(f,'name','اسم المسار','Workflow name','',null,true);const stepsInput=field(f,'steps','الخطوات','Steps','',null,true,'textarea');stepsInput.parentElement.hidden=true;const stepRows=N('div',undefined,'wide');f.prepend(stepRows);const steps=[{role:'line_manager',sla:3,label:'المدير المباشر'},{role:'hrbp',sla:3,label:'الموارد البشرية'},{role:'super_admin',sla:5,label:'الاعتماد النهائي'}];function drawSteps(){stepRows.replaceChildren();steps.forEach((s,i)=>{const row=N('div',undefined,'foundation-question'),name=N('input'),r=N('select'),days=N('input'),who=N('select');name.value=s.label;name.setAttribute('aria-label','اسم الخطوة / Step name');name.oninput=()=>{s.label=name.value;sync()};Object.entries(M.roles).filter(([k])=>k!=='top_management').forEach(([k,v])=>r.add(new Option(t(v[0],v[1]),k)));r.value=s.role;r.setAttribute('aria-label','دور المعتمد / Approver role');r.onchange=()=>{s.role=r.value;sync()};days.type='number';days.min=1;days.max=365;days.value=s.sla;days.setAttribute('aria-label','المهلة بالأيام / SLA days');days.oninput=()=>{s.sla=+days.value;sync()};who.add(new Option(t('حسب الدور','By role'),''));people().forEach(e=>who.add(new Option(e.employee_ar,String(e.employee_code))));who.value=s.assignee||'';who.setAttribute('aria-label','معتمد محدد / Specific approver');who.onchange=()=>{s.assignee=who.value;sync()};row.append(N('strong',t('الخطوة ','Step ')+num(i+1)),name,r,days,who);A.button(t('حذف','Remove'),()=>{steps.splice(i,1);drawSteps()},row);stepRows.append(row)});A.button(t('إضافة خطوة','Add step'),()=>{steps.push({role:'line_manager',sla:3,label:t('خطوة جديدة','New step')});drawSteps()},stepRows);sync()}function sync(){stepsInput.value=JSON.stringify(steps)}drawSteps();requestForm();}
function requestForm(){if(!F().workflowDefs.length)return;heading('طلب عبر مسار اعتماد','Submit a workflow request');const latest=F().workflowDefs.filter(d=>!F().workflowDefs.some(x=>x.id===d.id&&x.version>d.version));const f=form(A.content,v=>{const d=F().workflowDefs.find(d=>d.id+':'+d.version===v.workflow);commit('workflow.submit',v.employee_code,()=>F().workflowRequests.push({id:id(),employee_code:v.employee_code,title:v.title,detail:v.detail,requester:A.identity.value,workflow_id:d.id,version:d.version,steps:clone(d.steps),step:0,status:'pending',step_started:new Date().toISOString(),actions:[]}))});field(f,'workflow','المسار','Workflow','',latest.map(d=>[d.id+':'+d.version,d.name+' v'+d.version]),true);field(f,'employee_code','الموظف موضوع الطلب','Subject employee','',people().map(e=>[e.employee_code,e.employee_ar]),true);field(f,'title','عنوان الطلب','Request title','',null,true);field(f,'detail','التفاصيل','Details','',null,true,'textarea')}
function approvals(){const ids=new Set(people().map(e=>String(e.employee_code)));const rows=F().workflowRequests.filter(q=>ids.has(q.employee_code)||q.requester===A.identity.value);for(const q of rows){const box=N('article',undefined,'foundation-card'),step=q.steps[q.step];box.append(N('h3',q.title),N('p',q.detail),N('span',q.status+' · '+(step?.label||step?.role||'✓'),'foundation-tag'),N('p',t('الموظف: ','Employee: ')+q.employee_code));q.actions.forEach(a=>box.append(N('p',[a.date,a.action,a.actor,a.comment].join(' · '))));if(q.status==='pending'&&step&&(step.assignee?String(step.assignee)===A.identity.value:step.role===role())&&q.requester!==A.identity.value){const comment=N('textarea');comment.placeholder=t('تعليق — مطلوب للرفض والإرجاع','Comment — required for rejection / return');box.append(comment);for(const [action,ar,en]of [['approve','اعتماد','Approve'],['reject','رفض','Reject'],['return','إرجاع للتعديل','Return for revision']])A.button(t(ar,en),()=>{try{commit('workflow.'+action,q.id,()=>{const next=M.transition(q,action,{role:role(),employee:A.identity.value},comment.value);Object.assign(q,next)});A.draw()}catch(e){error.textContent=e.message}},box);const error=N('p',undefined,'foundation-error');box.append(error)}if(q.status==='returned'&&q.requester===A.identity.value){const f=form(box,v=>commit('workflow.resubmit',q.id,()=>{q.detail=v.detail;q.status='pending';q.step=0;q.step_started=new Date().toISOString();q.actions.push({action:'resubmit',actor:A.identity.value,date:new Date().toISOString(),comment:v.detail})}));field(f,'detail','تفاصيل الطلب المعدلة','Revised request details',q.detail,null,true,'textarea')}A.content.append(box)}if(!rows.length)msg('لا توجد طلبات جديدة ضمن النطاق.','No new requests in scope.');requestForm();heading('الطلبات السابقة','Legacy requests');const legacy=A.state.requests.filter(q=>ids.has(String(q.employee_code)));A.table(legacy,[['employee_code',t('الموظف','Employee')],['type',t('النوع','Type')],['detail',t('التفاصيل','Details')],['state',t('الحالة','Status')]]);msg('الطلبات السابقة محفوظة كما هي؛ مسارات الاعتماد الجديدة تُطبّق على الطلبات الجديدة فقط.','Legacy requests are preserved. New workflows apply to new requests only.')}
function foundation(){const rows=people(),grid=N('div',undefined,'foundation-grid');for(const [n,ar,en]of [[rows.length,'موظف ضمن النطاق','Employees in scope'],[jobs().length,'وظيفة','Jobs'],[competencies().length,'جدارة من القاموس','Dictionary competencies'],[rows.filter(e=>!e.contract_end).length,'نهاية عقد غير مسجلة','Missing contract end'],[rows.filter(e=>!e.probation_end).length,'نهاية تجربة غير مسجلة','Missing probation end'],[notifications().length,'تنبيه مستحق','Due alerts']]){const c=N('article',undefined,'foundation-card');c.append(N('strong',num(n)),N('p',t(ar,en)));grid.append(c)}A.content.append(N('div',t('Dar Academy · المرحلة الأولى: الأساس المشترك، دليل الوظائف وفهرس الجدارات. بيانات الشركة الأصلية محفوظة، وإضافات هذه المرحلة محلية.','Dar Academy · Phase 1: shared foundation, job catalog and competency dictionary. Company source data is preserved; additions are local.'),'foundation-banner'),grid);const f=form(A.content,v=>commit('settings.digits','settings',()=>F().settings.digits=v.digits));if(role()==='top_management')f.hidden=true;field(f,'digits','شكل الأرقام (الأكواد لا تتغير)','Digit display (IDs unchanged)',F().settings.digits,[['latn','0123456789'],['arab','٠١٢٣٤٥٦٧٨٩']]);msg('المراحل التالية — تقييم التجربة وتجديد العقود، الأكاديمية ومركز التقييم، عبء العمل والإحلال، والتحليلات — تنتظر مراجعة المرحلة الأولى.','Next phases — probation/renewal evaluations, Academy and Assessment Center, workload/succession and analytics — await Phase 1 review.');msg('المعاينة ليست نظامًا سحابيًا آمنًا: الأدوار ترشيح محلي، سجل التدقيق قابل للتعديل من تخزين المتصفح، والبريد غير متصل.','This preview is not a secure cloud system: roles filter locally, the browser audit log is mutable and email is disconnected.')}
function auditPage(){msg('يسجل تعديلات المرحلة الأولى مع الفاعل والدور والتوقيت. سجل محلي غير محصّن ضد تعديل المتصفح.','Phase 1 changes record actor, role and timestamp. The local log is not tamper-proof.');searchable(F().audit.slice().reverse().map(e=>({...e,change:JSON.stringify({before:e.before,after:e.after})})),[['date',t('التوقيت','Timestamp')],['actor',t('الفاعل','Actor')],['role',t('الدور','Role')],['action',t('الإجراء','Action')],['entity',t('الكيان','Entity')],['change',t('التغيير','Change')]])}
function bulk(){heading('تبادل البيانات عبر Excel','Exchange data through Excel');msg('نزّل ملف النطاق الحالي، عدّل الحقول ثم ارفعه. تُراجع التغييرات قبل الحفظ. لا يحذف الاستيراد صفوفًا ولا ينشئ موظفين أو وظائف من أكواد غير معروفة.','Download the current scope, edit fields and upload. Changes are reviewed before saving. Import does not delete rows or create employees/jobs from unknown IDs.');const kind=N('select'),box=N('div',undefined,'foundation-toolbar'),preview=N('div');[['employees','الموظفون','Employees'],['jobs','الوظائف','Jobs'],['competencies','الجدارات','Competencies'],['questions','أسئلة القوالب','Template questions']].forEach(([v,a,e])=>kind.add(new Option(t(a,e),v)));kind.setAttribute('aria-label','مجموعة بيانات Excel / Excel dataset');box.append(kind);const status=N('p');A.content.append(box,status,preview);const datasets=()=>({employees:{key:'employee_code',rows:people(),cols:['employee_code','employee_ar','employee_en','email','position_code','hire_date','employment_status','contract_type','contract_end','probation_end','site']},jobs:{key:'job_code',rows:jobs(),cols:['job_code','job_ar','job_en','grade','career_level','family_ar','classification','template_id','learning_path']},competencies:{key:'competency_code',rows:competencies(),cols:['competency_code','competency_name','name_en','competency_type','definition','definition_en','level_1','level_2','level_3','level_4','level_5','positive','negative','assessment_method','development_area']},questions:{key:'question_id',rows:F().templates.filter(x=>!F().templates.some(y=>y.id===x.id&&y.version>x.version)).flatMap(v=>v.sections.flatMap((s,si)=>s.questions.map(q=>({template_id:v.id,version:v.version,template_ar:v.name_ar,template_en:v.name_en,section_index:si,section_ar:s.title_ar,section_en:s.title_en,question_id:q.id,text_ar:q.text_ar,text_en:q.text_en,type:q.type,scale:q.scale||5,weight:q.weight||0,required:q.required?'yes':'no'})))),cols:['template_id','version','template_ar','template_en','section_index','section_ar','section_en','question_id','text_ar','text_en','type','scale','weight','required']}});
A.button(t('تنزيل Excel','Download Excel'),async()=>{try{status.textContent=t('جارٍ تجهيز الملف…','Preparing workbook…');const d=datasets()[kind.value],res=await fetch('/api/foundation/excel-export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:kind.value,columns:d.cols,rows:d.rows.map(r=>d.cols.map(k=>r[k]??''))})});if(!res.ok)throw Error((await res.json()).error);const url=URL.createObjectURL(await res.blob()),a=N('a');a.href=url;a.download='Dar-Academy-'+kind.value+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent=t('الملف جاهز.','Workbook ready.')}catch(e){status.textContent=e.message}},box);if(!editor())return;const upload=N('input');upload.type='file';upload.accept='.xlsx';upload.setAttribute('aria-label','رفع Excel للمراجعة / Upload Excel for review');box.append(upload);kind.onchange=()=>{preview.replaceChildren();upload.value=''};upload.onchange=async()=>{preview.replaceChildren();const file=upload.files[0];if(!file)return;const selectedKind=kind.value;try{status.textContent=t('جارٍ قراءة التغييرات…','Reading changes…');const res=await fetch('/api/foundation/excel-import',{method:'POST',body:file}),v=await res.json();if(!res.ok)throw Error(v.error);const d=datasets()[selectedKind],oldMap=new Map(d.rows.map(r=>[String(r[d.key]),r])),seen=new Set(),changes=[],diff=[];for(const row of v.rows){const key=String(row[d.key]??'').trim(),old=oldMap.get(key);if(!old)throw Error(t('كود غير معروف: ','Unknown ID: ')+key);if(seen.has(key))throw Error(t('كود مكرر: ','Duplicate ID: ')+key);seen.add(key);const patch={};for(const c of d.cols){if(!(c in row))throw Error(t('عمود مفقود: ','Missing column: ')+c);let val=row[c]??'';if(['employee_code','position_code','job_code','competency_code','template_id','question_id'].includes(c))val=String(val);if(['grade','scale','weight','section_index','version'].includes(c)&&val!==''){if(!Number.isFinite(+val))throw Error('Invalid numeric value: '+c);val=+val}if(/hire_date|contract_end|probation_end/.test(c)&&val){val=String(val).slice(0,10);if(M.day(val)===null)throw Error('Invalid Gregorian date: '+c)}if(String(old[c]??'').slice(0,c==='hire_date'?10:5001)!==String(val)){patch[c]=val;diff.push({code:key,field:c,before:old[c]??'',after:val})}}if(selectedKind==='employees'){if(patch.position_code&&!A.positions.some(p=>p.position_code===patch.position_code&&(!company()||find(A.jobs,'job_code',p.job_code)?.company_code===company())))throw Error('Invalid or out-of-company position');const merged={...old,...patch};for(const c of ['contract_end','probation_end'])if(merged[c]&&merged.hire_date&&merged[c]<String(merged.hire_date).slice(0,10))throw Error('End date before hire date')}if(selectedKind==='jobs'&&patch.classification&&!['Technical','Managerial','Admin','Labor'].includes(patch.classification))throw Error('Invalid classification');if(selectedKind==='questions'&&['template_id','question_id','section_index','version'].some(k=>k in patch))throw Error('Question/template IDs, section index and version must stay unchanged');if(Object.keys(patch).length)changes.push({key,old,patch})}A.table(diff,[['code',t('الكود','Code')],['field',t('الحقل','Field')],['before',t('قبل','Before')],['after',t('بعد','After')]],preview);status.textContent=num(changes.length)+' '+t('سجل متغير؛ راجع قبل التطبيق.','changed records; review before applying.');const apply=A.button(t('تطبيق التغييرات المعروضة محليًا','Apply displayed changes locally'),()=>{try{if(kind.value!==selectedKind)throw Error('Dataset changed');commit('excel.import',selectedKind,()=>{if(selectedKind==='questions'){const grouped=new Map();for(const c of changes){const oldTemplate=F().templates.find(x=>x.id===c.old.template_id&&x.version===+c.old.version);let draft=grouped.get(oldTemplate.id);if(!draft){draft=clone(oldTemplate);draft.version=Math.max(...F().templates.filter(x=>x.id===draft.id).map(x=>x.version))+1;draft.created=new Date().toISOString();grouped.set(draft.id,draft)}const s=draft.sections[+c.old.section_index],q=s.questions.find(x=>x.id===c.key),p=c.patch;if('template_ar'in p)draft.name_ar=p.template_ar;if('template_en'in p)draft.name_en=p.template_en;if('section_ar'in p)s.title_ar=p.section_ar;if('section_en'in p)s.title_en=p.section_en;for(const k of ['text_ar','text_en','type','scale','weight'])if(k in p)q[k]=p[k];if('required'in p){if(!['yes','no'].includes(p.required))throw Error('Required must be yes/no');q.required=p.required==='yes'}}for(const draft of grouped.values()){M.validateTemplate(draft);F().templates.push(draft)}}else for(const c of changes){const target=selectedKind==='employees'?F().employeeExtras:selectedKind==='jobs'?F().jobEdits:F().competencyEdits;upsert(target,d.key,{[d.key]:c.key,...c.patch});if(selectedKind==='employees'){const core={...find(A.state.edits,'employee_code',c.key),employee_code:c.key};for(const k of ['employee_ar','employee_en','email','position_code','hire_date','employment_status','contract_type'])if(k in c.patch)core[k]=c.patch[k];upsert(A.state.edits,'employee_code',core);const p=A.positions.find(p=>p.position_code===(c.patch.position_code||c.old.position_code));if(p){core.job_ar=find(A.jobs,'job_code',p.job_code)?.job_ar;upsert(A.state.edits,'employee_code',core)}}audit('excel.row',c.key,c.old,c.patch)}});A.rebuild();A.identities();A.draw()}catch(e){status.textContent=e.message}},preview);apply.disabled=!changes.length}catch(e){status.textContent=e.message;preview.replaceChildren()}};
}
function render(path){const pages={'/foundation':()=>{foundation();if(role()!=='top_management')bulk()},'/competencies':dictionary,'/competency-gaps':gaps,'/jobs':catalog,'/employees':()=>employeePage(),'/me':()=>employeePage(true),'/access':access,'/notifications':notificationPage,'/form-templates':templates,'/workflows':workflows,'/approvals':approvals,'/audit-log':auditPage};if(!pages[path])return false;pages[path]();return true}
let legacySnapshot=null;function trackLegacy(store){const keys=['reviews','requests','movements','accounts','policies','acks','edits','newEmployees','structureEdits','positionEdits','training','projects'];const current=Object.fromEntries(keys.map(k=>[k,JSON.stringify(store[k]||[])]));if(legacySnapshot)for(const k of keys)if(current[k]!==legacySnapshot[k])audit('legacy.update',k,JSON.parse(legacySnapshot[k]),JSON.parse(current[k]));legacySnapshot=current}trackLegacy(A.state);
window.ODFoundation={trackLegacy,routes:extraRoutes,allowRoute,scopedEmployees,render,requirements,role,notifications,roles:M.roles,number:num,pendingCount:()=>{const ids=new Set(people().map(e=>String(e.employee_code)));return F().workflowRequests.filter(q=>q.status==='pending'&&ids.has(q.employee_code)).length},scopedPositions:()=>{const c=company();if(editor()||role()==='top_management')return A.positions.filter(p=>!c||find(A.jobs,'job_code',p.job_code)?.company_code===c);const ids=new Set(scopedEmployees(A.employees).map(e=>e.position_code)),binding=F().bindings.find(b=>b.employee_code===A.identity.value&&b.role===role()),sub=A.below(binding?.org_code||A.org(A.me()));return A.positions.filter(p=>(!c||find(A.jobs,'job_code',p.job_code)?.company_code===c)&&(role()==='site_manager'?!!binding?.site&&p.project_site===binding.site:role()==='assessor'||role()==='employee'?ids.has(p.position_code):sub.has(String(p.org_code))))}};
const ready=setInterval(()=>{if(!A.employees.length||!document.querySelector('.side-footer'))return;clearInterval(ready);F();if(!F().seeded){F().seeded=true;F().templates.push({id:'sample-hse',version:1,name_ar:'مناقشة جدارات السلامة بالموقع — مثال',name_en:'Site HSE competency discussion — sample',sample:true,status:'draft',created:new Date().toISOString(),sections:[{title_ar:'الأدلة السلوكية',title_en:'Behavioral evidence',questions:[{id:'hse-evidence',text_ar:'اذكر موقفًا طبقت فيه إجراء السلامة بالموقع مع الدليل.',text_en:'Describe a site safety procedure you applied and provide evidence.',type:'textarea',required:true,weight:0,scale:5},{id:'hse-level',text_ar:'المستوى المرصود مع شرح المقيّم',text_en:'Observed proficiency with assessor explanation',type:'rating',required:true,weight:100,scale:5}]}]});A.save()}A.role.style.display='none';document.querySelector('.side-footer').insertBefore(roleSelect,A.role);A.role.value=M.roles[role()][2];roleSelect.onchange=()=>{localStorage.setItem('od.previewRole',role());A.role.value=M.roles[role()][2];window.ODShell.roleChanged()};A.draw()},250);
